/** @module user-passkey-management */

import { getComponentStyles } from '@auth0/universal-components-core';
import { MoreVertical, Trash2, UserRoundKey } from 'lucide-react';
import * as React from 'react';

import { PasskeyActionModal } from '@/components/auth0/my-account/shared/passkey/passkey-action-modal';
import { GateKeeper } from '@/components/auth0/shared/gate-keeper/gate-keeper';
import { Header } from '@/components/auth0/shared/header';
import { StyledScope } from '@/components/auth0/shared/styled-scope';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuPortal,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Spinner } from '@/components/ui/spinner';
import { useUserPasskey } from '@/hooks/my-account/use-user-passkey';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type {
  UserPasskeyMgmtViewProps,
  UserPasskeyMgmtProps,
} from '@/types/my-account/passkey/passkey-types';

/**
 * Passkey management component.
 * @param props - Component props
 * @param props.customMessages - Custom translation messages to override defaults
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.hideHeader - Whether to hide the header
 * @param props.addAction - Configuration for the add passkey action
 * @param props.revokeAction - Configuration for the revoke passkey action
 * @param props.onFetch - Callback after passkeys are loaded
 * @param props.onErrorAction - Callback when an action errors
 * @returns JSX element
 * @internal
 */
function UserPasskeyMgmt(props: UserPasskeyMgmtProps) {
  const {
    customMessages = {},
    styling = { variables: { common: {}, light: {}, dark: {} }, classes: {} },
    hideHeader = false,
    addAction,
    revokeAction,
    onFetch,
    onErrorAction,
  } = props;

  const {
    passkeys,
    isLoading,
    isEnrolling,
    isRevoking,
    disableAdd,
    disableRevoke,
    isRevokeModalOpen,
    currentPasskey,
    setIsRevokeModalOpen,
    handleAddPasskey,
    handleRevokePasskey,
    handleConfirmRevoke,
  } = useUserPasskey({
    customMessages,
    addAction,
    revokeAction,
    onFetch,
    onErrorAction,
  });

  return (
    <GateKeeper isLoading={isLoading} styling={styling}>
      <UserPasskeyMgmtView
        passkeys={passkeys}
        isEnrolling={isEnrolling}
        isRevoking={isRevoking}
        styling={styling}
        customMessages={customMessages}
        hideHeader={hideHeader}
        disableAdd={disableAdd}
        disableRevoke={disableRevoke}
        isRevokeModalOpen={isRevokeModalOpen}
        currentPasskey={currentPasskey}
        handleAddPasskey={handleAddPasskey}
        handleRevokePasskey={handleRevokePasskey}
        handleConfirmRevoke={handleConfirmRevoke}
        setIsRevokeModalOpen={setIsRevokeModalOpen}
      />
    </GateKeeper>
  );
}

/**
 * UserPasskeyMgmtView — presentational component.
 * @internal
 * @param props - {@link UserPasskeyMgmtViewProps}
 * @returns View component
 */
function UserPasskeyMgmtView(props: UserPasskeyMgmtViewProps) {
  const {
    passkeys,
    isEnrolling,
    isRevoking,
    styling,
    customMessages,
    hideHeader,
    disableAdd,
    disableRevoke,
    isRevokeModalOpen,
    currentPasskey,
    handleAddPasskey,
    handleRevokePasskey,
    handleConfirmRevoke,
    setIsRevokeModalOpen,
  } = props;

  const { isDarkMode } = useTheme();
  const { t } = useTranslator('passkey', customMessages);
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const hasPasskeys = passkeys.length > 0;

  return (
    <StyledScope style={currentStyles.variables}>
      {!hideHeader && <Header title={t('header.title')} description={t('header.description')} />}

      <Card className={cn(currentStyles.classes?.['UserPasskeyMgmt-root'])}>
        <CardHeader>
          <CardTitle className="flex flex-wrap items-center gap-2 sm:gap-3">
            <span className="text-base text-(length:--font-size-body) font-semibold text-card-foreground">
              {t('section_title')}
            </span>
            {hasPasskeys && (
              <Badge variant="success" size="sm" className="shrink-0" aria-label={t('enabled')}>
                {t('enabled')}
              </Badge>
            )}
          </CardTitle>
          {!hasPasskeys && <CardDescription>{t('no_passkeys')}</CardDescription>}
          {!disableAdd && (
            <CardAction>
              <Button
                size="default"
                variant="outline"
                className="text-sm w-full sm:w-auto shrink-0"
                onClick={handleAddPasskey}
                disabled={isEnrolling}
                aria-busy={isEnrolling}
                aria-label={t('add_passkey')}
              >
                {isEnrolling ? (
                  <Spinner size="sm" colorScheme="primary" aria-hidden="true" />
                ) : (
                  t('add_passkey')
                )}
              </Button>
            </CardAction>
          )}
        </CardHeader>

        {hasPasskeys && (
          <CardContent className="space-y-2">
            {passkeys.map((passkey) => (
              <Card
                key={passkey.id}
                className={cn(currentStyles.classes?.['UserPasskeyMgmt-item'])}
              >
                <CardHeader className="flex flex-row items-center gap-3">
                  <UserRoundKey
                    className="h-4 w-4 shrink-0 text-muted-foreground"
                    aria-hidden="true"
                  />
                  <div className="flex flex-col gap-0.5 flex-1 min-w-0">
                    <CardTitle className="text-base text-(length:--font-size-body) font-semibold text-card-foreground">
                      {passkey.name}
                    </CardTitle>
                    {(passkey.deviceInfo || passkey.createdAt || passkey.lastUsedAt) && (
                      <CardDescription className="flex flex-wrap items-center gap-x-1.5">
                        {passkey.deviceInfo && <span>{passkey.deviceInfo}</span>}
                        {passkey.createdAt && (
                          <>
                            {passkey.deviceInfo && <span aria-hidden="true">•</span>}
                            <span>
                              {t('created_at', {
                                date: new Date(passkey.createdAt).toLocaleDateString(),
                              })}
                            </span>
                          </>
                        )}
                        {passkey.lastUsedAt && (
                          <>
                            {(passkey.deviceInfo || passkey.createdAt) && (
                              <span aria-hidden="true">•</span>
                            )}
                            <span>
                              {t('last_used', {
                                date: new Date(passkey.lastUsedAt).toLocaleDateString(),
                              })}
                            </span>
                          </>
                        )}
                      </CardDescription>
                    )}
                  </div>
                  {!disableRevoke && (
                    <DropdownMenu>
                      <DropdownMenuTrigger
                        aria-label={passkey.name}
                        className="h-8 w-8 p-0 rounded-xl bg-primary border border-primary/20 shadow-sm transition-all duration-200 hover:bg-primary/90 hover:shadow-md focus:outline-none focus:ring-2 focus:ring-primary/50 shrink-0"
                      >
                        <MoreVertical className="h-4 w-4 text-primary-foreground" />
                      </DropdownMenuTrigger>
                      <DropdownMenuPortal>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem
                            onClick={() => handleRevokePasskey(passkey)}
                            className="text-destructive-foreground focus:text-destructive-foreground"
                          >
                            <Trash2 className="mr-2 h-4 w-4" />
                            {t('actions.revoke')}
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenuPortal>
                    </DropdownMenu>
                  )}
                </CardHeader>
              </Card>
            ))}
          </CardContent>
        )}
      </Card>

      <PasskeyActionModal
        open={isRevokeModalOpen}
        onOpenChange={setIsRevokeModalOpen}
        isPending={isRevoking}
        onConfirm={handleConfirmRevoke}
        name={currentPasskey?.name}
        styling={styling}
        customMessages={customMessages?.modals?.revoke}
      />
    </StyledScope>
  );
}

/**
 * Passkey management component.
 *
 * Displays enrolled passkeys with options to add and revoke.
 *
 * @param props - {@link UserPasskeyMgmtProps}
 * @param props.customMessages - Custom i18n message overrides
 * @param props.styling - CSS variables and class overrides
 * @param props.hideHeader - Hide the header section
 * @param props.addAction - Lifecycle hooks for the add passkey operation
 * @param props.revokeAction - Lifecycle hooks for the revoke passkey operation
 * @param props.onFetch - Callback after passkeys are loaded
 * @param props.onErrorAction - Callback when an action errors
 * @returns Passkey management component
 *
 * @see {@link UserPasskeyMgmtProps} for full props documentation
 *
 * @example
 * ```tsx
 * <UserPasskeyMgmt
 *   addAction={{ onAfter: () => console.log('Passkey added') }}
 *   revokeAction={{ onAfter: (passkey) => console.log('Revoked:', passkey.name) }}
 *   onErrorAction={(error, action) => console.error(action, error)}
 * />
 * ```
 */
export { UserPasskeyMgmt, UserPasskeyMgmtView };

/**
 * Passkey revoke confirmation modal.
 * @module passkey-action-modal
 * @internal
 */

import { getComponentStyles } from '@auth0/universal-components-core';
import * as React from 'react';

import { Modal } from '@/components/ui/modal';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type { PasskeyActionModalProps } from '@/types/my-account/passkey/passkey-types';

const DEFAULT_STYLING: PasskeyActionModalProps['styling'] = {
  variables: { common: {}, light: {}, dark: {} },
  classes: {},
};

/**
 * Passkey revoke confirmation modal.
 * @param props - Modal props including open state and action callbacks.
 * @returns The passkey action modal component.
 */
export function PasskeyActionModal(props: PasskeyActionModalProps) {
  const {
    open,
    onOpenChange,
    onConfirm,
    isPending,
    name: passkeyName,
    styling = DEFAULT_STYLING,
    customMessages = {},
  } = props;

  const { t } = useTranslator('passkey.modals.revoke', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const handleOpenChange = React.useCallback(
    (open: boolean) => {
      if (!isPending) onOpenChange(open);
    },
    [isPending, onOpenChange],
  );

  const content = (
    <p className="text-(length:--font-size-paragraph) font-normal text-primary">
      <>
        {t.trans('consent', {
          components: {
            bold: (children: string) => <strong key="passkey-name">{children}</strong>,
          },
          vars: { name: passkeyName ?? '' },
        })}
      </>
    </p>
  );

  return (
    <Modal
      open={open}
      onOpenChange={handleOpenChange}
      className={cn(currentStyles.classes?.['PasskeyActionModal-modalContent'])}
      title={t('title')}
      content={content}
      modalActions={{
        isLoading: isPending,
        nextAction: {
          type: 'button',
          label: t('confirm'),
          onClick: onConfirm,
          variant: 'destructive',
          disabled: isPending,
        },
        previousAction: {
          label: t('cancel'),
          onClick: () => handleOpenChange(false),
        },
      }}
    />
  );
}

/**
 * Form action buttons component.
 * @module form-actions
 * @internal
 */

import type { ActionButton } from '@auth0/universal-components-core';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { cn } from '@/lib/utils';

export interface FormActionsProps<T = void> {
  hasUnsavedChanges?: boolean;
  isLoading?: boolean;
  nextAction?: Partial<ActionButton<T>>;
  previousAction?: Partial<ActionButton<T>>;
  showPrevious?: boolean;
  showNext?: boolean;
  showUnsavedChanges?: boolean;
  align?: 'left' | 'right';
  className?: string;
  unsavedChangesText?: string;
}

const DEFAULT_NEXT_ACTION: ActionButton = {
  type: 'submit',
  label: 'Save',
  variant: 'primary',
  onClick: () => {},
};

const DEFAULT_PREVIOUS_ACTION: ActionButton = {
  label: 'Cancel',
  variant: 'outline',
  onClick: () => {},
};

export const FormActions: React.FC<FormActionsProps> = ({
  hasUnsavedChanges = false,
  isLoading = false,
  nextAction,
  previousAction,
  className,
  showPrevious = true,
  showNext = true,
  showUnsavedChanges = true,
  align = 'right',
  unsavedChangesText = 'Unsaved changes',
}) => {
  const nextButtonProps = React.useMemo(
    () => ({ ...DEFAULT_NEXT_ACTION, ...nextAction }),
    [nextAction],
  );

  const previousButtonProps = React.useMemo(
    () => ({ ...DEFAULT_PREVIOUS_ACTION, ...previousAction }),
    [previousAction],
  );

  const handleNextClick = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      nextButtonProps.onClick(e.nativeEvent);
    },
    [nextButtonProps.onClick],
  );

  const handlePreviousClick = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      previousButtonProps.onClick(e.nativeEvent);
    },
    [previousButtonProps.onClick],
  );

  const showUnsavedIndicator = showUnsavedChanges && hasUnsavedChanges;
  const isPreviousVisible = showUnsavedChanges ? showPrevious && hasUnsavedChanges : showPrevious;

  return (
    <div
      className={cn(
        'flex flex-row items-center gap-2 p-2',
        align === 'right' ? 'justify-end' : 'justify-start',
        className,
      )}
    >
      {showUnsavedIndicator && (
        <span className="text-sm text-muted-foreground">{unsavedChangesText}</span>
      )}

      {showPrevious && (
        <Button
          type="button"
          variant={previousButtonProps.variant}
          size={previousButtonProps.size}
          onClick={handlePreviousClick}
          disabled={
            previousButtonProps.disabled || isLoading || (showUnsavedChanges && !hasUnsavedChanges)
          }
          className={cn(
            'FormActions-previous',
            showUnsavedChanges && !isPreviousVisible && 'invisible',
          )}
          aria-hidden={showUnsavedChanges && !isPreviousVisible}
          tabIndex={isPreviousVisible ? 0 : -1}
        >
          {previousButtonProps.label}
        </Button>
      )}

      {showNext && (
        <Button
          type={nextButtonProps.type}
          variant={nextButtonProps.variant}
          size={nextButtonProps.size}
          disabled={nextButtonProps.disabled || isLoading}
          className="FormActions-next min-w-17.5"
          {...(nextButtonProps.type !== 'submit' && { onClick: handleNextClick })}
        >
          {isLoading ? (
            <Spinner
              colorScheme={nextButtonProps.variant === 'destructive' ? 'primary' : 'foreground'}
              size="sm"
              aria-hidden="true"
            />
          ) : (
            <>
              {nextButtonProps.icon && (
                <span className="mr-2" aria-hidden="true">
                  {nextButtonProps.icon as React.ReactNode}
                </span>
              )}
              {nextButtonProps.label}
            </>
          )}
        </Button>
      )}
    </div>
  );
};

/**
 * GateKeeper component for guarding content during loading, MFA step-up, and 5xx error states.
 * @module gate-keeper
 * @internal
 */

import {
  type ComponentStyling,
  getComponentStyles,
  getStatusCode,
  isMfaRequiredError,
} from '@auth0/universal-components-core';
import { RefreshCcw } from 'lucide-react';
import React, { useCallback, useMemo, useState, useEffect } from 'react';

import { StyledScope } from '@/components/auth0/shared/styled-scope';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardTitle } from '@/components/ui/card';
import { Spinner } from '@/components/ui/spinner';
import { useCoreClient } from '@/hooks/shared/use-core-client';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { useGateKeeperContext } from '@/providers/gate-keeper-context';

interface GateKeeperProps {
  styling?: ComponentStyling<Record<string, string>>;
  isLoading?: boolean;
  children: React.ReactNode;
}

/**
 * Blocking error fallback with retry button.
 * Shown for 5xx errors and dismissed MFA errors.
 *
 * @param props - Component props.
 * @param props.onRetry - Retry handler.
 * @returns Error fallback element.
 * @internal
 */
function ErrorFallback({ onRetry, isMfa }: { onRetry: () => void; isMfa?: boolean }) {
  const { t } = useTranslator('gate_keeper');
  const key = isMfa ? 'mfa_error' : 'fallback';

  return (
    <Card className="text-center">
      <CardContent className="flex flex-col items-center gap-2">
        <CardTitle>{t(`${key}.title`)}</CardTitle>
        <CardDescription>{t(`${key}.description`)}</CardDescription>
      </CardContent>
      {!isMfa && (
        <CardFooter className="justify-center">
          <Button variant="primary" size="default" onClick={onRetry}>
            <RefreshCcw className="size-4" />
            {t('fallback.retry')}
          </Button>
        </CardFooter>
      )}
    </Card>
  );
}

/**
 * Guards children from rendering during loading/error states. MFA step-up overlays
 * children without unmounting them, preserving any in-progress form state.
 * - Loading → spinner (blocks children)
 * - MFA required error → MFA step-up dialog overlaid on children
 * - 5xx error or dismissed MFA → blocking error fallback with retry
 * - No error → children
 *
 * @param props - Component props.
 * @param props.styling - Styling configuration forwarded to the styled scope.
 * @param props.isLoading - Whether content is loading.
 * @param props.children - Child elements to render on success.
 * @returns GateKeeper element.
 */
export function GateKeeper({ styling, isLoading, children }: GateKeeperProps) {
  const { error, onRetry } = useGateKeeperContext();
  const { coreClient } = useCoreClient();
  const { isDarkMode } = useTheme();
  const [isRetrying, setIsRetrying] = useState(false);

  const styles = useMemo(() => getComponentStyles(styling, isDarkMode), [styling, isDarkMode]);

  const handleRetry = useCallback(async () => {
    setIsRetrying(true);
    try {
      await onRetry?.();
    } finally {
      setIsRetrying(false);
    }
  }, [onRetry]);

  const isMfaStepUp = isMfaRequiredError(error);
  const statusCode = getStatusCode(error);
  const isSystemError = !!error && !!statusCode && statusCode >= 500;

  useEffect(() => {
    if (isMfaStepUp && coreClient && !coreClient.isProxyMode()) {
      console.warn(
        `🚨 [Auth0 Components Warning]: A step-up authentication (MFA) was triggered, but the interactiveErrorHandler is not configured.\n\nTo enable Universal Login redirects for MFA step-up, login required, or consent errors, please update your configuration:\n\n<Auth0Provider\n  ...\n  interactiveErrorHandler="popup"\n>\n\nFor more details, refer to the Auth0 Documentation.`,
      );
    }
  }, [isMfaStepUp, coreClient]);

  if (isLoading || isRetrying) {
    return (
      <StyledScope style={styles.variables}>
        <div className="flex items-center justify-center p-8">
          <Spinner />
        </div>
      </StyledScope>
    );
  }

  if (isSystemError || isMfaStepUp) {
    return (
      <StyledScope style={styles.variables}>
        <ErrorFallback onRetry={handleRetry} isMfa={isMfaStepUp} />
      </StyledScope>
    );
  }

  return <StyledScope style={styles.variables}>{children}</StyledScope>;
}

/**
 * Section header with actions.
 * @module header
 * @internal
 */

import type { ActionButton as CoreActionButton } from '@auth0/universal-components-core';
import type { LucideIcon } from 'lucide-react';
import { ArrowLeft } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { Switch } from '@/components/ui/switch';
import { Tooltip, TooltipTrigger, TooltipContent } from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

export interface TooltipProps {
  content: React.ReactNode | string;
}

export interface WithTooltipProps {
  trigger: React.ReactNode | string;
  tooltip: TooltipProps;
}

export interface BaseActionProps extends Omit<CoreActionButton, 'icon' | 'onClick'> {
  icon?: LucideIcon;
  className?: string;
  hidden?: boolean;
  tooltip?: TooltipProps;
}

export interface ButtonActionProps extends BaseActionProps {
  type: 'button';
  onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
}

export interface SwitchActionProps extends Omit<BaseActionProps, 'type' | 'label'> {
  type: 'switch';
  checked?: boolean;
  onCheckedChange: (checked: boolean) => void;
  'aria-label'?: string;
}

export type ActionProps = ButtonActionProps | SwitchActionProps;

export interface HeaderProps {
  title?: string;
  description?: string;
  backButton?: {
    text?: string;
    icon?: LucideIcon;
    onClick: (e: React.MouseEvent<HTMLButtonElement>) => void;
  };
  actions?: ActionProps[];
  isLoading?: boolean;
  className?: string;
}

const WithTooltip: React.FC<WithTooltipProps> = ({ trigger, tooltip }) => (
  <>
    <Tooltip>
      <TooltipTrigger asChild>
        <div>{trigger}</div>
      </TooltipTrigger>
      <TooltipContent>{tooltip.content}</TooltipContent>
    </Tooltip>
  </>
);

const ButtonAction: React.FC<ButtonActionProps> = ({
  icon: Icon,
  className,
  label,
  onClick,
  disabled,
  variant,
  size,
}) => (
  <Button
    onClick={onClick}
    disabled={disabled}
    variant={variant}
    size={size}
    className={cn('flex items-center gap-2 w-full sm:w-auto sm:min-w-fit', className)}
    aria-label={label}
  >
    {Icon && <Icon className="h-4 w-4 flex-shrink-0" aria-hidden="true" />}
    <span className="truncate">{label}</span>
  </Button>
);

const SwitchAction: React.FC<SwitchActionProps> = ({
  className,
  'aria-label': ariaLabel,
  checked,
  onCheckedChange,
  disabled,
}) => (
  <div className={cn('flex items-center gap-2', className)}>
    <Switch
      checked={checked}
      onCheckedChange={onCheckedChange}
      disabled={disabled}
      aria-label={ariaLabel}
    />
  </div>
);

export const Header = React.forwardRef<
  HTMLDivElement,
  HeaderProps & React.HTMLAttributes<HTMLDivElement>
>(({ title, description, backButton, actions, isLoading, className, ...props }, ref) => {
  const BackIcon = backButton?.icon || ArrowLeft;

  const renderAction = (action: ActionProps, index: number) => {
    const key = `action-${index}`;
    if (isLoading) {
      return <Spinner key={`spinner-${key}`} className="w-4 h-4" />;
    }
    if (action.hidden) {
      return null;
    }
    const actionElement =
      action.type === 'switch' ? (
        <SwitchAction key={key} {...action} />
      ) : (
        <ButtonAction key={key} {...action} />
      );
    if (action.tooltip) {
      return (
        <WithTooltip key={`tooltip-${key}`} trigger={actionElement} tooltip={action.tooltip} />
      );
    }
    return actionElement;
  };

  return (
    <div
      ref={ref}
      className={cn('w-full mb-8', className)}
      role="banner"
      aria-label={title ? `${title} header` : 'Header'}
      {...props}
    >
      {backButton && (
        <Button
          variant="link"
          onClick={backButton.onClick}
          size="default"
          className="flex items-center text-sm mb-3"
          aria-label={backButton.text || 'Go back'}
        >
          <BackIcon className="h-4 w-4" aria-hidden="true" />
          {backButton.text && <span>{backButton.text}</span>}
        </Button>
      )}

      <div className="flex items-start justify-between gap-4">
        <div className="flex flex-col min-w-0 flex-1">
          {title && (
            <h1
              className={cn(
                'text-xl sm:text-2xl text-primary md:text-4xl font-bold leading-tight break-words text-left text-(length:--font-size-page-header) mb-0',
              )}
            >
              {title}
            </h1>
          )}
          {description && (
            <p
              className={cn(
                'text-base text-muted-foreground leading-relaxed break-words text-left text-(length:--font-size-page-description) mt-2',
              )}
            >
              {description}
            </p>
          )}
        </div>

        {actions && actions.length > 0 && (
