import {
  createPasskeyCredential,
  passkeyQueryKeys,
  parsePublicKeyCreationOptions,
  parseUserAgent,
  type CreatePasskeyResponse,
  type PasskeyAuthMethodResponse,
} from '@auth0/universal-components-core';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { useCoreClient } from '@/hooks/shared/use-core-client';
import { useTranslator } from '@/hooks/shared/use-translator';
import type {
  Passkey,
  UseUserPasskeyServiceResult,
} from '@/types/my-account/passkey/passkey-types';

/**
 * Internal service hook for passkey CRUD operations.
 * @returns Query and mutation handlers for listing, enrolling, revoking, and renaming passkeys.
 * @internal
 */
export function useUserPasskeyService(): UseUserPasskeyServiceResult {
  const { coreClient } = useCoreClient();
  const queryClient = useQueryClient();
  const { t } = useTranslator('passkey');

  const passkeysQuery = useQuery<Passkey[]>({
    queryKey: passkeyQueryKeys.list(),
    queryFn: async () => {
      const client = coreClient!.getMyAccountApiClient();
      const response = await client.authenticationMethods.list();
      return response.authentication_methods
        .filter((m) => (m as PasskeyAuthMethodResponse).type === 'passkey')
        .map((m, index) => {
          const passkey = m as PasskeyAuthMethodResponse;
          return {
            id: passkey.id,
            name: t('passkey_name', { index: index + 1 }),
            createdAt: passkey.created_at,
            lastUsedAt: passkey.last_auth_at,
            deviceInfo: parseUserAgent(passkey.user_agent),
          };
        });
    },
    enabled: !!coreClient,
  });

  const invalidateList = () => queryClient.invalidateQueries({ queryKey: passkeyQueryKeys.list() });

  const enrollMutation = useMutation<boolean, Error, void>({
    mutationFn: async () => {
      const client = coreClient!.getMyAccountApiClient();

      const startResponse = (await client.authenticationMethods.create({
        type: 'passkey',
      })) as CreatePasskeyResponse;
      const { auth_session, authn_params_public_key } = startResponse;
      const authenticationMethodId = 'passkey|new';

      const authnResponse = await createPasskeyCredential(
        parsePublicKeyCreationOptions(authn_params_public_key),
      );
      if (!authnResponse) return false;

      await client.authenticationMethods.verify(authenticationMethodId, {
        auth_session,
        authn_response: authnResponse,
      });
      return true;
    },
    onSuccess: (enrolled) => {
      if (enrolled) invalidateList();
    },
  });

  const revokeMutation = useMutation<void, Error, string>({
    mutationFn: (id) => coreClient!.getMyAccountApiClient().authenticationMethods.delete(id),
    onSuccess: invalidateList,
  });

  return { passkeysQuery, enrollMutation, revokeMutation };
}

/**
 * Passkey management logic hook.
 * @module use-user-passkey
 */

import { useCallback, useEffect, useState } from 'react';

import { showToast } from '@/components/auth0/shared/toast';
import { useUserPasskeyService } from '@/hooks/my-account/shared/services/use-user-passkey-service';
import { useErrorHandler } from '@/hooks/shared/use-error-handler';
import { useTranslator } from '@/hooks/shared/use-translator';
import type {
  Passkey,
  UseUserPasskeyOptions,
  UseUserPasskeyReturn,
} from '@/types/my-account/passkey/passkey-types';

type ActiveModal = { mode: 'revoke'; passkey: Passkey } | null;

/**
 * Hook for passkey management UI state and handlers.
 * @param options - UseUserPasskeyOptions
 * @returns State and handlers for UserPasskeyMgmt.
 */
export function useUserPasskey({
  customMessages,
  addAction,
  revokeAction,
  onFetch,
  onErrorAction,
}: UseUserPasskeyOptions): UseUserPasskeyReturn {
  const { t } = useTranslator('passkey', customMessages);
  const handleError = useErrorHandler();

  const { passkeysQuery, enrollMutation, revokeMutation } = useUserPasskeyService();

  const disableAdd = !!addAction?.disabled;
  const disableRevoke = !!revokeAction?.disabled;
  const readOnly = !passkeysQuery.isLoading && disableAdd && disableRevoke;

  const [activeModal, setActiveModal] = useState<ActiveModal>(null);

  const isRevokeModalOpen = activeModal?.mode === 'revoke';
  const currentPasskey = activeModal?.passkey ?? null;

  const closeModal = useCallback((open: boolean) => {
    if (!open) setActiveModal(null);
  }, []);

  useEffect(() => {
    if (passkeysQuery.isSuccess) onFetch?.();
  }, [passkeysQuery.isSuccess, onFetch]);

  useEffect(() => {
    if (passkeysQuery.isError) {
      handleError(passkeysQuery.error);
    }
  }, [passkeysQuery.isError, passkeysQuery.error, handleError]);

  const handleAddPasskey = useCallback(async () => {
    if (disableAdd) return;
    if (addAction?.onBefore && !addAction.onBefore()) return;
    try {
      const enrolled = await enrollMutation.mutateAsync();
      if (!enrolled) return;
      addAction?.onAfter?.();
      showToast({ type: 'success', message: t('success.add') });
    } catch (err) {
      handleError(err);
      onErrorAction?.(err as Error, 'add');
    }
  }, [disableAdd, addAction, enrollMutation, onErrorAction, t, handleError]);

  const handleRevokePasskey = useCallback(
    (passkey: Passkey) => {
      if (disableRevoke) return;
      if (revokeAction?.onBefore && !revokeAction.onBefore(passkey)) return;
      setActiveModal({ mode: 'revoke', passkey });
    },
    [disableRevoke, revokeAction],
  );

  const handleConfirmRevoke = useCallback(async () => {
    if (!currentPasskey) return;
    try {
      await revokeMutation.mutateAsync(currentPasskey.id);
      revokeAction?.onAfter?.(currentPasskey);
      showToast({ type: 'success', message: t('success.revoke') });
    } catch (err) {
      handleError(err);
      onErrorAction?.(err as Error, 'revoke');
    } finally {
      setActiveModal(null);
    }
  }, [currentPasskey, revokeAction, revokeMutation, onErrorAction, t, handleError]);

  return {
    passkeys: passkeysQuery.data ?? [],
    isLoading: passkeysQuery.isLoading,
    isEnrolling: enrollMutation.isPending,
    isRevoking: revokeMutation.isPending,
    disableAdd,
    disableRevoke,
    readOnly,
    isRevokeModalOpen,
    currentPasskey,
    setIsRevokeModalOpen: closeModal,
    handleAddPasskey,
    handleRevokePasskey,
    handleConfirmRevoke,
  };
}

/**
 * CoreClient initialization hook.
 * @module use-core-client-initialization
 * @internal
 */

import type {
  CoreClientInterface,
  AuthDetails,
  I18nInitOptions,
  TelemetryConfig,
  TelemetryComponentGetter,
} from '@auth0/universal-components-core';
import { createCoreClient } from '@auth0/universal-components-core';
import * as React from 'react';

interface UseCoreClientInitializationProps {
  authDetails: AuthDetails;
  i18nOptions?: I18nInitOptions;
  telemetry: TelemetryConfig;
  getComponent: TelemetryComponentGetter;
}

/**
 * @internal
 * @param props - Initialization props.
 * @returns The initialized CoreClient instance, or null while initializing.
 */
export const useCoreClientInitialization = ({
  authDetails,
  i18nOptions,
  telemetry,
  getComponent,
}: UseCoreClientInitializationProps): CoreClientInterface | null => {
  const { authProxyUrl } = authDetails;
  const [coreClient, setCoreClient] = React.useState<CoreClientInterface | null>(null);

  React.useEffect(() => {
    // Wait for CSS detection to complete before initializing (skip if telemetry disabled)
    if (telemetry.enabled && telemetry.css === 'unknown') {
      return;
    }

    const initializeCoreClient = async () => {
      try {
        const initializedCoreClient = await createCoreClient(
          authDetails,
          i18nOptions,
          telemetry,
          getComponent,
        );
        setCoreClient(initializedCoreClient);
      } catch (error) {
        console.error(error);
      }
    };
    initializeCoreClient();
  }, [authProxyUrl, i18nOptions, telemetry, getComponent]);

  return coreClient;
};

